INSERT INTO `downloads` (`id`, `title`, `description`, `category_type`, `file_path`, `cover_image`, `file_type`, `file_size`, `download_count`, `created_at`, `updated_at`) VALUES
(1, 'Panduan Kurikulum Tahfidz Al-Qur\'an 2 Juz SMPS IT SIT Madani', 'Modul resmi kurikulum tahfidz mutqin Sekolah Islam Terpadu Madani Kayuagung berbasis standar JSIT Indonesia.', 'E-Book', '/uploads/downloads/panduan-mutqin-tahfidz-madani.pdf', '/uploads/covers/cover-tahfidz-mutqin.webp', 'PDF', '9.0 KB', 349, '2026-09-19 21:27:08', '2026-11-11 20:40:37'),
(2, 'Buku Saku Adab & 10 Karakter (Muwashofat) Siswa JSIT', 'Pedoman pembiasaan akhlak islami, adab kepada guru dan orang tua, tata tertib siswa asrama dan sekolah.', 'E-Book', '/uploads/downloads/buku-saku-adab-karakter-siswa.pdf', '/uploads/covers/cover-karakter-santri.webp', 'PDF', '6.9 KB', 291, '2026-09-19 21:27:08', '2026-11-11 20:20:01'),
(3, 'Petunjuk Praktikum Laboratorium IPA Terpadu SMPS IT Madani', 'Pedoman eksperimen laboratorium biologi dan fisika untuk siswa kelas VII-IX SIT Madani Kayuagung.', 'E-Book', '/uploads/downloads/petunjuk-praktikum-sains-terpadu.pdf', '/uploads/covers/cover-praktikum-sains.webp', 'PDF', '6.6 KB', 201, '2026-09-19 21:27:08', '2026-11-11 20:44:50'),
(4, 'Kurikulum Pembinaan Da\'i Muda, Khitabah & Public Speaking', 'Kumpulan materi public speaking, retorika dakwah 3 bahasa (Indonesia, Arab, Inggris), dan sistematika kultum.', 'E-Book', '/uploads/downloads/kurikulum-pembinaan-dai-muda.pdf', '/uploads/covers/cover-dai-muda.webp', 'PDF', '6.5 KB', 217, '2026-09-19 21:27:08', '2026-11-11 20:14:50'),
(5, 'Buku Saku Kosakata Harian Bilingual Bahasa Arab & Inggris Siswa', 'Modul percakapan bilingual harian asrama dan lingkungan sekolah untuk mempercepat penguasaan active speaking.', 'E-Book', '/uploads/downloads/buku-saku-kosakata-bilingual.pdf', '/uploads/covers/cover-bilingual-arab-inggris.webp', 'PDF', '6.6 KB', 319, '2026-09-19 21:27:08', '2026-11-11 20:24:25'),
(6, 'Panduan Sukses Asesmen Nasional & Masuk Sekolah Lanjutan Unggulan Favorit', 'Strategi sukses menembus sekolah lanjutan favorit impian, pembedahan materi literasi dan numerasi Asesmen Nasional.', 'E-Book', '/uploads/downloads/panduan-sukses-snbt-ptn.pdf', '/uploads/covers/cover-sukses-snbt.webp', 'PDF', '6.6 KB', 456, '2026-09-19 21:27:08', '2026-11-11 20:10:27'),
(7, 'Logo Resmi SMPS IT SIT Madani Kayuagung (High Resolution)', 'File logo resmi Sekolah Islam Terpadu Madani Kayuagung format PNG transparan.', 'Logo', '/uploads/logo-madani.png', NULL, 'PNG', '120 KB', 785, '2026-09-19 21:27:08', '2026-11-13 15:32:28'),
(8, 'Logo Lambang SIT Madani Square HD', 'Logo lambang persegi Sekolah Islam Terpadu Madani Kayuagung format PNG.', 'Logo', '/uploads/logo-madani-square.png', NULL, 'PNG', '85 KB', 321, '2026-09-19 21:27:08', '2026-11-13 15:25:28');
INSERT INTO `dpcs` (`id`, `name`, `slug`, `description`, `head_name`, `address`, `thumbnail`, `order`, `created_at`, `updated_at`) VALUES
(1, 'Program Tahfidz 2 Juz Mutqin & Hadits', 'program-tahfidz-2-juz-mutqin', 'Bimbingan intensif membaca Al-Qur\'an dengan tartil, tahsin bersanad, dan hafalan mutqin minimal 2 juz serta 12 hadits pilihan.', NULL, 'Kurikulum Khusus Keislaman', NULL, 1, '2026-09-19 21:27:08', '2026-09-19 21:27:08'),
(2, 'Bina Pribadi Islam (BPI) & Karakter Islami', 'bina-pribadi-islam-bpi', 'Halaqah pekanan pembinaan adab, pembiasaan ibadah yaumiyah, dzikir ma\'tsurat, serta penanaman akhlaqul karimah.', NULL, 'Pembinaan Karakter Siswa', NULL, 2, '2026-09-19 21:27:08', '2026-09-19 21:27:08'),
(3, 'Kurikulum Terpadu JSIT & Kurikulum Merdeka', 'kurikulum-terpadu-jsit-merdeka', 'Memadukan standar capaian Kurikulum Merdeka Nasional dengan nilai-nilai Islam Terpadu berstandar JSIT Indonesia.', NULL, 'Integrasi Nilai Islam & Sains', NULL, 3, '2026-09-19 21:27:08', '2026-09-19 21:27:08'),
(4, 'Program Belajar Bersama Maestro & Riset Sains', 'belajar-bersama-maestro-riset', 'Eksplorasi bakat seni, budaya, sains dan teknologi langsung bersama tokoh dan pakar di bidangnya.', NULL, 'Pengembangan Akademik & Potensi', NULL, 4, '2026-09-19 21:27:08', '2026-09-19 21:27:08'),
(5, 'Madani Safar & Outing Class Edukatif', 'madani-safar-outing-class', 'Pembelajaran luar kelas berbasis observasi alam, rihlah edukatif, studi lingkungan, dan pengembangan wawasan santri SIT Madani di Kabupaten Ogan Komering Ilir.', NULL, 'Outdoor Learning & Wawasan', NULL, 5, '2026-09-19 21:27:08', '2026-09-19 21:27:08'),
(6, 'Madani Peduli & Bakti Sosial Masyarakat', 'madani-peduli-bakti-sosial', 'Kiprah nyata santri SIT Madani dalam melayani, menebar kebaikan, dan memberikan kontribusi positif bagi masyarakat di Kabupaten Ogan Komering Ilir (Kayuagung).', NULL, 'Kepedulian Sosial & Dakwah', NULL, 6, '2026-09-19 21:27:08', '2026-09-19 21:27:08');
